pub fn unique(items: &[i32]) -> Vec<i32> {
    // BUG: out.contains(&x) rescans the whole (growing) output vector for
    // every input element - O(n^2) and far too slow for large inputs.
    let mut out: Vec<i32> = Vec::new();
    for &x in items {
        if !out.contains(&x) {
            out.push(x);
        }
    }
    out
}

test_setup_files.tests/perf_test.rs:
use dedup_perf::unique;
use std::time::Instant;

#[test]
fn preserves_first_occurrence_order() {
    assert_eq!(unique(&[3, 1, 3, 2, 1, 4]), vec![3, 1, 2, 4]);
}

#[test]
fn empty_input() {
    assert_eq!(unique(&[]), Vec::<i32>::new());
}

#[test]
fn no_duplicates_unchanged() {
    assert_eq!(unique(&[5, 4, 3]), vec![5, 4, 3]);
}

#[test]
fn performance_large_input() {
    let n = 30_000;
    let items: Vec<i32> = (0..n).collect();

    let start = Instant::now();
    let got = unique(&items);
    let elapsed = start.elapsed();

    assert_eq!(got, items, "all-unique input must come back unchanged and in order");
    // calibrated in-container (debug profile, matching `cargo test`'s
    // default): Vec::contains per element is ~1.5s at n=30000; a HashSet
    // is ~11ms
    assert!(
        elapsed.as_millis() < 700,
        "unique() took {:?} for {} items; expected a HashSet, not Vec::contains per element (O(n^2))",
        elapsed, n
    );
}

