use std::collections::HashSet;

pub fn unique(items: &[i32]) -> Vec<i32> {
    // First-occurrence order preserved; a HashSet gives O(1) membership.
    let mut seen: HashSet<i32> = HashSet::new();
    let mut out: Vec<i32> = Vec::new();
    for &x in items {
        if seen.insert(x) {
            out.push(x);
        }
    }
    out
}

